.darma-loader-darma-b16-monorail-glide { --accent: var(--loader-color, #0284c7); --accent-2: var(--loader-secondary-color, #e0f2fe); width: var(--loader-size, 134px); height: calc(var(--loader-size, 134px) * .56); position: relative; overflow: hidden; }
.darma-loader-darma-b16-monorail-glide .darma-loader-darma-b16-monorail-glide__beam { position: absolute; left: 0; right: 0; top: 46%; height: 8%; border-radius: 3px; background: linear-gradient(#cbd5e1, #64748b); }
.darma-loader-darma-b16-monorail-glide .darma-loader-darma-b16-monorail-glide__pylon { position: absolute; top: 54%; width: 5%; height: 46%; background: color-mix(in srgb, var(--accent) 35%, transparent); animation: darma-loader-darma-b16-monorail-glide-rail-pass calc(var(--loader-speed, 1s) * 2.6) linear infinite; }
.darma-loader-darma-b16-monorail-glide .darma-loader-darma-b16-monorail-glide__pylon:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * -1.3); }
.darma-loader-darma-b16-monorail-glide .darma-loader-darma-b16-monorail-glide__car { position: absolute; left: 6%; top: 12%; width: 56%; height: 34%; border-radius: 16px 8px 6px 6px / 50% 30% 6px 6px; background: linear-gradient(var(--accent-2), var(--accent)); box-shadow: 0 4px 0 color-mix(in srgb, #000 25%, transparent); animation: darma-loader-darma-b16-monorail-glide-rail-glide calc(var(--loader-speed, 1s) * 2.6) cubic-bezier(.5, 0, .5, 1) infinite; }
.darma-loader-darma-b16-monorail-glide .darma-loader-darma-b16-monorail-glide__car::after { content: ''; position: absolute; left: 12%; top: 30%; width: 66%; height: 34%; border-radius: 3px; background: repeating-linear-gradient(90deg, color-mix(in srgb, #0f172a 55%, transparent) 0 24%, transparent 0 34%); }
@keyframes darma-loader-darma-b16-monorail-glide-rail-pass { from { left: 104%; } to { left: -6%; } }
@keyframes darma-loader-darma-b16-monorail-glide-rail-glide { 0% { transform: translateX(-120%); } 40%, 60% { transform: translateX(0); } 100% { transform: translateX(120%); } }

